export type Listener<Payload> = (payload: Payload) => void;

export type Unsubscribe = () => void;

export interface Emitter<Events extends Record<string, unknown>> {
  on<Name extends keyof Events & string>(
    name: Name,
    listener: Listener<Events[Name]>,
  ): Unsubscribe;
  off<Name extends keyof Events & string>(
    name: Name,
    listener: Listener<Events[Name]>,
  ): void;
  emit<Name extends keyof Events & string>(
    name: Name,
    payload: Events[Name],
  ): void;
}

export function createEmitter<
  Events extends Record<string, unknown>,
>(): Emitter<Events> {
  const listeners = new Map<keyof Events & string, Set<Listener<never>>>();

  const on: Emitter<Events>['on'] = (name, listener) => {
    let set = listeners.get(name);
    if (set === undefined) {
      set = new Set();
      listeners.set(name, set);
    }
    const stored = listener as Listener<never>;
    set.add(stored);
    let active = true;
    return () => {
      if (!active) {
        return;
      }
      active = false;
      const current = listeners.get(name);
      if (current === undefined) {
        return;
      }
      current.delete(stored);
      if (current.size === 0) {
        listeners.delete(name);
      }
    };
  };

  const off: Emitter<Events>['off'] = (name, listener) => {
    const set = listeners.get(name);
    if (set === undefined) {
      return;
    }
    set.delete(listener as Listener<never>);
    if (set.size === 0) {
      listeners.delete(name);
    }
  };

  const emit: Emitter<Events>['emit'] = (name, payload) => {
    const set = listeners.get(name);
    if (set === undefined) {
      return;
    }
    for (const listener of [...set]) {
      try {
        (listener as Listener<Events[typeof name]>)(payload);
      } catch {
        // A throwing listener must not prevent the others from running.
      }
    }
  };

  return { on, off, emit };
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { createEmitter } from './events';

type Events = {
  ping: { id: number };
  message: string;
};

describe('createEmitter', () => {
  it('calls listeners with the typed payload', () => {
    const emitter = createEmitter<Events>();
    const seen: number[] = [];
    emitter.on('ping', (payload) => {
      seen.push(payload.id);
    });

    emitter.emit('ping', { id: 1 });
    emitter.emit('ping', { id: 2 });

    assert.deepEqual(seen, [1, 2]);
  });

  it('only notifies listeners registered for that event', () => {
    const emitter = createEmitter<Events>();
    const messages: string[] = [];
    emitter.on('message', (payload) => {
      messages.push(payload);
    });

    emitter.emit('ping', { id: 1 });

    assert.deepEqual(messages, []);
  });

  it('returns an unsubscribe function from on', () => {
    const emitter = createEmitter<Events>();
    let calls = 0;
    const unsubscribe = emitter.on('ping', () => {
      calls += 1;
    });

    emitter.emit('ping', { id: 1 });
    unsubscribe();
    emitter.emit('ping', { id: 2 });

    assert.equal(calls, 1);
  });

  it('unsubscribing twice is safe', () => {
    const emitter = createEmitter<Events>();
    let calls = 0;
    const unsubscribe = emitter.on('ping', () => {
      calls += 1;
    });

    unsubscribe();
    unsubscribe();
    emitter.emit('ping', { id: 1 });

    assert.equal(calls, 0);
  });

  it('removes a listener with off', () => {
    const emitter = createEmitter<Events>();
    let calls = 0;
    const listener = (): void => {
      calls += 1;
    };

    emitter.on('ping', listener);
    emitter.emit('ping', { id: 1 });
    emitter.off('ping', listener);
    emitter.emit('ping', { id: 2 });

    assert.equal(calls, 1);
  });

  it('keeps other listeners running when one throws', () => {
    const emitter = createEmitter<Events>();
    const seen: string[] = [];

    emitter.on('ping', () => {
      seen.push('first');
      throw new Error('boom');
    });
    emitter.on('ping', () => {
      seen.push('second');
    });
    emitter.on('ping', () => {
      seen.push('third');
    });

    assert.doesNotThrow(() => {
      emitter.emit('ping', { id: 1 });
    });
    assert.deepEqual(seen, ['first', 'second', 'third']);
  });

  it('notifies a listener added during emit only on the next emit', () => {
    const emitter = createEmitter<Events>();
    const seen: string[] = [];

    emitter.on('ping', () => {
      seen.push('outer');
      emitter.on('ping', () => {
        seen.push('inner');
      });
    });

    emitter.emit('ping', { id: 1 });
    assert.deepEqual(seen, ['outer']);

    emitter.emit('ping', { id: 2 });
    assert.deepEqual(seen, ['outer', 'outer', 'inner']);
  });
});
